use std::path::PathBuf;

use clap::Parser;
use exposed::{config::Config, inbound::http::server::serve_exposed};

#[derive(Parser)]
struct Cli {
    config: PathBuf,
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let args = Cli::parse();

    let config = Config::try_from(&args.config)?;

    let services = async {
        if let Some(imports) = &config.imports {
            tokio::try_join!(
                serve_exposed(&config),
                exposed::imports::serve(imports, &config.connection_string)
            )?;
        } else {
            serve_exposed(&config).await?;
        }
        Ok(())
    };
    tokio::select! {
        result = services => result,
        signal = tokio::signal::ctrl_c() => { signal?; Ok(()) }
    }
}
#![deny(
    clippy::all,
    clippy::restriction,
    clippy::pedantic,
    clippy::nursery,
    clippy::cargo,
    missing_docs,
    warnings
)]

//! The exposed project serves declaration data from MPs in the UK parliament.

/// Contains the domain models for the project.
pub mod domain;

/// Contains the inbound adapters for the project
pub mod inbound;

/// Contains the outbound adapters for the project
pub mod outbound;

/// Contains the configuration parameters for this project
pub mod config;

/// Importing and refreshing Parliament evidence.
pub mod imports;
use std::{fs::read_to_string, io::Error as IoError, path::PathBuf};
use thiserror::Error;

use serde::Deserialize;

#[derive(Deserialize)]
/// Config for the exposed application
pub struct Config {
    /// Postgres conn string
    pub connection_string: String,
    /// Port for server to listen on
    pub port: u16,
    /// Optional import runtime; omitted configurations continue to serve search only.
    pub imports: Option<crate::imports::config::ImportConfig>,
}

impl TryFrom<&PathBuf> for Config {
    type Error = ConfigError;
    fn try_from(value: &PathBuf) -> Result<Self, Self::Error> {
        let raw = read_to_string(value)?;
        let config = rust_yaml::from_str(&raw)?;
        Ok(config)
    }
}

#[derive(Error, Debug)]
/// Collection of errors when parsing configuration
pub enum ConfigError {
    #[error("yaml malformatted")]
    /// Yaml cannot be parsed
    FormattingError(#[from] rust_yaml::Error),
    #[error("unable to read config")]
    /// Config path invalid
    FileNotFound(#[from] IoError),
}
//! This module contains the `exposed` domains.

pub mod models;
pub mod repositories;
pub mod services;
//! A collection of outbound adapters for the `exposed` project

mod funder;
mod parliament_member;
mod postgres;

pub use postgres::ExposedDatabase;
//! Adapters for data that flows into the `exposed` application.

pub mod http;
//! General purpose postgres client

use sqlx::PgPool;

/// Postgres client that wraps [sqlx::Pool]
#[derive(Clone)]
pub struct ExposedDatabase {
    pool: PgPool,
}

impl ExposedDatabase {
    /// Creates a new instance of [ExposedDatabase]
    pub async fn new(conn_str: &str) -> Self {
        let pool = PgPool::connect(conn_str).await.unwrap();

        Self { pool }
    }

    /// Get a reference to the underlying pool
    pub fn pool(&self) -> &PgPool {
        &self.pool
    }
}

impl From<PgPool> for ExposedDatabase {
    fn from(value: PgPool) -> Self {
        Self { pool: value }
    }
}

#[cfg(test)]
mod test_scaffolding {
    use sqlx::PgPool;

    #[sqlx::test(migrations = "../db/migrations")]
    async fn migrations_work(pool: PgPool) -> sqlx::Result<()> {
        let res = sqlx::query!("SELECT name FROM members")
            .fetch_all(&pool)
            .await;
        assert!(res.is_ok());
        Ok(())
    }

    #[sqlx::test(
        migrations = "../db/migrations",
        fixtures(
            "../../../../db/fixtures/add_members.sql",
            "../../../../db/fixtures/add_declarations_and_funding_entries.sql"
        )
    )]
    async fn fixtures_work(pool: PgPool) -> sqlx::Result<()> {
        let res = sqlx::query!("SELECT name FROM members")
            .fetch_all(&pool)
            .await?;
        assert_eq!(res.len(), 2);

        let res = sqlx::query!("SELECT * FROM declarations")
            .fetch_all(&pool)
            .await?;
        assert_eq!(res.len(), 2);

        let res = sqlx::query!("SELECT * FROM funders")
            .fetch_all(&pool)
            .await?;
        assert_eq!(res.len(), 2);

        let res = sqlx::query!("SELECT * FROM funding_entries")
            .fetch_all(&pool)
            .await?;
        assert_eq!(res.len(), 2);

        Ok(())
    }
}
use std::sync::Arc;

use crate::domain::services::entity_search::EntitySearchService;

#[derive(Clone)]
/// State required to run the exposed app
pub struct AppState<E: EntitySearchService> {
    /// Entity search service
    pub entity_search_service: Arc<E>,
}
use std::sync::Arc;

use crate::{
    config::Config,
    domain::services::entity_search::Service as EntitySearchService,
    inbound::http::{routes::routes, state::AppState},
    outbound::ExposedDatabase,
};

/// Starts an `exposed` HTTP server
pub async fn serve_exposed(config: &Config) -> anyhow::Result<()> {
    let db = ExposedDatabase::new(&config.connection_string).await;
    let service = EntitySearchService::new(db.clone(), db);

    let state = AppState {
        entity_search_service: Arc::new(service),
    };
    let router = routes().with_state(state);

    let port = config.port;
    let listener = tokio::net::TcpListener::bind(format!("0.0.0.0:{port}"))
        .await
        .unwrap();

    let _ = axum::serve(listener, router).await?;

    Ok(())
}
use axum::{Router, routing::get};

use crate::{
    domain::services::entity_search::EntitySearchService,
    inbound::http::{handlers, state::AppState},
};

/// Routes for the exposed application
pub fn routes<E: EntitySearchService>() -> Router<AppState<E>> {
    Router::new().route("/search", get(handlers::search_entities))
}

