import httpx
import pytest

from exposed.operator import OperatorError, run_import
from exposed.source import SourceClient


def test_committed_acknowledgement_controls_next_fetch_and_result():
    events = []

    def parliament(request):
        events.append("fetch")
        return httpx.Response(200, json={"raw": "untouched"})

    def application(request):
        if request.method == "DELETE":
            return httpx.Response(200, json={"status": "cancelled"})
        if request.url.path.endswith("evidence"):
            events.append("commit")
            return httpx.Response(200, json={"result": {"status": "succeeded", "members": 1}})
        events.append("begin")
        return httpx.Response(
            200, json={"sequence": 0, "request": {"operation": "current-members", "offset": 0}}
        )

    with httpx.Client(transport=httpx.MockTransport(parliament)) as api:
        with httpx.Client(base_url="http://app", transport=httpx.MockTransport(application)) as app:
            result = run_import("members", None, app, SourceClient(api, sleep=lambda _: None))
    assert events == ["begin", "fetch", "commit"]
    assert result == {"status": "succeeded", "members": 1}


def test_server_failure_stops_acquisition():
    def application(request):
        return httpx.Response(200, json={"error": "Another import is running"})

    def unexpected(request):
        pytest.fail("No Parliament request should be made")

    with httpx.Client(transport=httpx.MockTransport(unexpected)) as api:
        with httpx.Client(base_url="http://app", transport=httpx.MockTransport(application)) as app:
            with pytest.raises(OperatorError, match="Another import"):
                run_import("members", None, app, SourceClient(api))
"""The production Python package must remain an API transport."""

import ast
from pathlib import Path


def test_python_has_no_database_or_domain_dependencies():
    root = Path(__file__).parents[1] / "src" / "exposed"
    forbidden = {"psycopg", "sqlalchemy", "pydantic", "exposed.core", "exposed.db"}
    for file in root.rglob("*.py"):
        for node in ast.walk(ast.parse(file.read_text())):
            if isinstance(node, ast.Import):
                modules = [alias.name for alias in node.names]
            elif isinstance(node, ast.ImportFrom):
                modules = [node.module or ""]
            else:
                continue
            assert not any(
                module == name or module.startswith(name + ".")
                for module in modules
                for name in forbidden
            ), file
use super::core::members::{HouseMembership, MemberHistory};
use chrono::NaiveDate;

fn date(value: &str) -> NaiveDate {
    NaiveDate::parse_from_str(value, "%Y-%m-%d").unwrap()
}

#[test]
fn service_clips_continuous_membership_but_preserves_a_real_gap() {
    let history = MemberHistory {
        id: 7,
        memberships: vec![
            HouseMembership {
                house: 1,
                start: date("1987-06-11"),
                end: Some(date("2025-01-01")),
            },
            HouseMembership {
                house: 1,
                start: date("2025-06-01"),
                end: None,
            },
        ],
    };
    let periods = history
        .service(date("2024-07-04"), date("2026-09-15"), true)
        .unwrap();
    assert_eq!(periods.len(), 2);
    assert_eq!(periods[0].source_start, date("1987-06-11"));
    assert_eq!(periods[0].served_from, date("2024-07-04"));
    assert_eq!(periods[0].end, Some(date("2025-01-01")));
    assert_eq!(periods[1].served_from, date("2025-06-01"));
}

#[test]
fn declaration_projection_matches_python_characterizations() {
    let cases: serde_json::Value =
        serde_json::from_str(include_str!("tests/declaration_cases.json")).unwrap();
    for (index, case) in cases.as_array().unwrap().iter().enumerate() {
        let result = super::adapters::declarations::interpret(&case["source"]);
        if case["rejected"] == true {
            assert!(result.is_err(), "case {index} should reject");
        } else {
            let actual =
                serde_json::to_value(result.unwrap_or_else(|e| panic!("case {index}: {e}")))
                    .unwrap();
            assert_eq!(actual, case["draft"], "case {index}");
        }
    }
}

#[test]
fn declaration_amounts_preserve_large_json_integers_and_still_reject_floats() {
    let amount = "1000000000000000000000000000001";
    let mut raw = refresh::declaration(101, 1, "10");
    raw["versions"][0]["fields"][1]["value"] = serde_json::from_str(amount).unwrap();
    let draft = super::adapters::declarations::interpret(&raw).unwrap();
    assert_eq!(
        draft.funding[0].amount.as_ref().unwrap().to_string(),
        amount
    );
    for value in ["10.0", "0.1", "1e30"] {
        raw["versions"][0]["fields"][1]["value"] = serde_json::from_str(value).unwrap();
        assert!(super::adapters::declarations::interpret(&raw).is_err());
    }
}

#[test]
fn latest_version_ties_compare_uninterpreted_numeric_evidence_exactly() {
    let mut raw = refresh::declaration(101, 1, "10");
    let mut other = raw["versions"][0].clone();
    raw["versions"][0]["unknown"] = serde_json::json!(-0.0);
    other["unknown"] = serde_json::json!(0.0);
    raw["versions"].as_array_mut().unwrap().push(other);
    assert!(super::adapters::declarations::interpret(&raw).is_err());
}
