fn main() { tokio::runtime::Runtime::new().unwrap().block_on(run()); }
async fn run() {
    let admin_url="REDACTED";
    let admin=PgPool::connect(admin_url).await.unwrap();
    let db=format!("exposed_review_lock_{}",std::process::id());
    sqlx::query(sqlx::AssertSqlSafe(format!("CREATE DATABASE {db}"))).execute(&admin).await.unwrap();
    let direct_url=admin_url.replace("/postgres?",&format!("/{db}?"));
    let direct=PgPoolOptions::new().max_connections(1).connect(&direct_url).await.unwrap();
    let listener=TcpListener::bind("127.0.0.1:0").await.unwrap();
    let port=listener.local_addr().unwrap().port();
    let hold=Arc::new(AtomicBool::new(false));
    let blocked=Arc::new(Notify::new());
    let release=Arc::new(Notify::new());
    let h=hold.clone(); let b=blocked.clone(); let r=release.clone();
    let proxy=tokio::spawn(async move {
        while let Ok((client,_))=listener.accept().await {
            let h=h.clone(); let b=b.clone(); let r=r.clone();
            tokio::spawn(async move {
                let server=TcpStream::connect("127.0.0.1:55432").await.unwrap();
                let (mut cr,mut cw)=client.into_split(); let (mut sr,mut sw)=server.into_split();
                let outbound=tokio::spawn(async move { let _=tokio::io::copy(&mut cr,&mut sw).await; });
                let mut buf=[0u8;65536];
                loop {
                    let n=sr.read(&mut buf).await.unwrap_or(0); if n==0 {break;}
                    if h.load(Ordering::SeqCst) { b.notify_one(); r.notified().await; }
                    if cw.write_all(&buf[..n]).await.is_err() {break;}
                }
                outbound.abort();
            });
        }
    });
    let pool=PgPoolOptions::new().max_connections(1).test_before_acquire(false).connect(&direct_url.replace(":55432/",&format!(":{port}/"))).await.unwrap();
    // Warm the exact cached statement, then release its first acquisition.
    let lock_sql="SELECT pg_try_advisory_lock(20260925, 1)";
    assert!(sqlx::query_scalar::<_,bool>(lock_sql).fetch_one(&pool).await.unwrap());
    assert!(sqlx::query_scalar::<_,bool>("SELECT pg_advisory_unlock(20260925, 1)").fetch_one(&pool).await.unwrap());
    while pool.num_idle()==0 {tokio::time::sleep(Duration::from_millis(10)).await;}
    hold.store(true,Ordering::SeqCst);
    let store=PostgresStore::new(pool.clone());
    let task=tokio::spawn(async move {store.acquire().await});
    tokio::time::timeout(Duration::from_secs(5),blocked.notified()).await.unwrap();
    // The server has acquired the lock but its result is paused in the proxy.
    let held=sqlx::query_scalar::<_,i64>("SELECT COUNT(*) FROM pg_locks WHERE locktype='advisory' AND classid=20260925 AND objid=1 AND database=(SELECT oid FROM pg_database WHERE datname=current_database())").fetch_one(&direct).await.unwrap();
    println!("Lock held on server before cancelling acquisition: {held}");
    task.abort(); let _=task.await;
    hold.store(false,Ordering::SeqCst); release.notify_one();
    tokio::time::timeout(Duration::from_secs(5),async {while pool.num_idle()==0 {tokio::time::sleep(Duration::from_millis(10)).await;}}).await.unwrap();
    let acquired_after_cancel=sqlx::query_scalar::<_,bool>(lock_sql).fetch_one(&direct).await.unwrap();
    println!("Pooled idle connections after cancellation: {}",pool.num_idle());
    println!("Independent connection can acquire after cancellation: {acquired_after_cancel}");
    pool.close().await;
    let acquired_after_close=sqlx::query_scalar::<_,bool>(lock_sql).fetch_one(&direct).await.unwrap();
    println!("Independent connection can acquire after closing pool: {acquired_after_close}");
    sqlx::query("SELECT pg_advisory_unlock_all()").execute(&direct).await.unwrap();
    direct.close().await; proxy.abort();
    sqlx::query(sqlx::AssertSqlSafe(format!("DROP DATABASE {db}"))).execute(&admin).await.unwrap(); admin.close().await;
    assert_eq!(held,1); assert!(!acquired_after_cancel); assert!(acquired_after_close);
}
