}

impl ImportError {
    pub fn source_failure(
        operation: impl Into<String>,
        cause: impl std::error::Error + Send + Sync + 'static,
    ) -> Self {
        Self::SourceFailure {
            operation: operation.into(),
            cause: Box::new(cause),
        }
    }
}

