    state.authorize(&headers)?;
    let refresh = state
        .store
        .refresh_state(state.config.term_start)
        .await
        .map_err(|error| {
            eprintln!("Import status: {error:?}");
            bad(
                StatusCode::INTERNAL_SERVER_ERROR,
                "Could not read refresh state",
            )
        })?;
    Ok(Json(json!(refresh)))
}

