+import { expect, test } from "@playwright/test";
+
+test("live search preserves API ranking, spelling, duplicates and entity context", async ({
+  page,
+}) => {
+  const entities = [
+    { name: "john lewis partnership", kind: "Funder", funder_kind: "Company" },
+    { name: "John Cooper", kind: "MP", funder_kind: null },
+    { name: "John Kinder", kind: "Funder", funder_kind: "Individual" },
+    { name: "john lewis partnership", kind: "Funder", funder_kind: "Company" },
+    { name: "John Union", kind: "Funder", funder_kind: "Trade Union" },
+    { name: "John Trust", kind: "Funder", funder_kind: "Not Specified" },
+    { name: "John Foundation", kind: "Funder", funder_kind: null },
+  ];
+  const requests: URL[] = [];
+  await page.route("**/api/search?*", async (route) => {
+    requests.push(new URL(route.request().url()));
+    await route.fulfill({ json: { entities } });
+  });
+  await page.goto("/");
+  const input = page.getByRole("searchbox");
+  await input.fill("jo");
+  await expect(
+    page.getByText("Type 1 more character to search."),
+  ).toBeVisible();
+  await input.press("Enter");
+  expect(requests).toHaveLength(0);
+  await input.fill("  John  ");
+  await expect(
+    page.getByRole("heading", { name: "7 results shown" }),
+  ).toBeVisible();
+  expect(requests).toHaveLength(1);
+  expect(requests[0].searchParams.get("term")).toBe("John");
+  expect(requests[0].searchParams.get("max_entries")).toBe("10");
+  expect(requests[0].searchParams.get("strictness")).toBe("1");
+  await expect(page.locator(".entity-name")).toHaveText(
+    entities.map((entity) => entity.name),
+  );
+  await expect(page.locator(".entity-kind-label")).toHaveText([
+    "Company",
+    "Individual",
+    "Company",
+    "Trade union",
+    "Unclassified",
+    "Unclassified",
+  ]);
+  await expect(page.locator(".entity-kind-label").first()).toBeVisible();
+  await expect(
+    page.locator(".entity-row").nth(1).locator(".entity-kind"),
+  ).toHaveCount(0);
+  expect(
+    await page
+      .locator(".entity-indicator:not(.entity-kind) .entity-icon")
+      .evaluateAll((icons) =>
+        icons.map((icon) => icon.getAttribute("aria-label")),
+      ),
+  ).toEqual([
+    "Funder: Company",
+    "MP",
+    "Funder: Individual",
+    "Funder: Company",
+    "Funder: Trade union",
+    "Funder: Unclassified",
